package com.mannvaasam.controller;
import com.mannvaasam.model.*; import com.mannvaasam.repo.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/sellers") public class SellerRegistrationController { final UserRepository users; final SellerProfileRepository sellers; final PasswordEncoder enc; public SellerRegistrationController(UserRepository u,SellerProfileRepository s,PasswordEncoder e){users=u;sellers=s;enc=e;}
@PostMapping("/register") public Map<String,Object> register(@RequestBody Map<String,String> b){String email=b.get("email");if(email==null||b.get("password")==null)throw new IllegalArgumentException("Email and password are required");if(users.findByEmail(email).isPresent())throw new IllegalArgumentException("Email already registered");User u=new User();u.name=b.getOrDefault("name","Seller");u.email=email;u.phone=b.get("phone");u.passwordHash=enc.encode(b.get("password"));u.role=Role.SELLER;users.save(u);SellerProfile s=new SellerProfile();s.user=u;s.businessName=b.getOrDefault("businessName",u.name);s.address=b.get("address");s.contact=u.phone;s.deliveryRadiusKm=25.0;s.deliveryDays=3;sellers.save(s);return Map.of("message","Seller registered","userId",u.id);}}
